package net.officefloor.hq.app.claim;

import java.util.Set;

/** Where a claim is in its life: added as a draft, opened, then settled. A clerk's settle of a claim
 * whose due is above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects
 * it (back to OPEN). A draft, open or pending claim can be voided, and a settled one by a steward
 * within 7 days of its settlement. A voided claim cannot change status. A draft can be DELETED, and a
 * deleted claim made a DRAFT again (restored) on the same sheet-today it was deleted. A claim opened while its
 * due is above the review threshold in force on its date goes to REVIEW instead of OPEN, counting nowhere,
 * until a steward reviews it (OPEN); a claim in REVIEW can also be voided. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether a claim in this status counts toward what its person has claimed and is due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is still open: OPEN, or PENDING, which is handled like OPEN
     * (it goes overdue, bears the late charge). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may move to {@code next}. */
    public boolean canBecome(ClaimStatus next) {
        return switch (this) {
            case DRAFT -> Set.of(OPEN, VOID, DELETED, REVIEW).contains(next);
            case REVIEW -> Set.of(OPEN, VOID).contains(next);
            case OPEN -> Set.of(PENDING, SETTLED, VOID).contains(next);
            case PENDING -> Set.of(OPEN, SETTLED, VOID).contains(next);
            case SETTLED -> next == VOID;
            case VOID -> false;
            case DELETED -> next == DRAFT;
        };
    }
}
package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.history.AsOfGuard;
import net.officefloor.hq.app.history.SheetHistory;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The periods of a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/periods")
@Validated
public class PeriodController {

    /** A period, with whether it is closed, whether that is only a soft close, and the due-total fixed when it was closed (null while it is
     * open) and each person's due-total for it and carried figure into it fixed then, by person id (empty while it is open), sent
     * and each person's opening balance for it, by person id, sent as text with two decimals so they are never rounded on the way. */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, Integer cap, boolean closed,
            boolean soft, String closedTotal, Map<Long, String> closedPersonTotals,
            Map<Long, String> closedPersonCarried, Map<Long, String> personOpenings, boolean locked) {
        static PeriodView of(Period period) {
            Map<Long, String> personTotals = new TreeMap<>();
            period.getClosedPersonTotals().forEach((id, total) -> personTotals.put(id, text(total)));
            Map<Long, String> personCarried = new TreeMap<>();
            period.getClosedPersonCarried().forEach((id, carried) -> personCarried.put(id, text(carried)));
            Map<Long, String> openings = new TreeMap<>();
            period.getPersonOpenings().forEach((id, opening) -> openings.put(id, text(opening)));
            return new PeriodView(period.getId(), period.getName(), period.getFrom(), period.getTo(), period.getCap(),
                    period.isClosed(), period.isSoft(), period.getClosedTotal() == null ? null : text(period.getClosedTotal()),
                    personTotals, personCarried, openings, period.isLocked());
        }

        private static String text(BigDecimal amount) {
            return amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
    }

    /** A period's name (not blank, no spaces inside, kept without the spaces around it) and its from
     * and to dates, both inclusive, and the most OPEN or PENDING claims each person may have in it: a
     * whole number of at least one, blank or missing for no cap. */
    public record PeriodRequest(
            @NotBlank @Size(max = 100) @Pattern(regexp = "\\s*\\S+\\s*") String name,
            @NotNull LocalDate from,
            @NotNull LocalDate to,
            @Pattern(regexp = "\\s*(\\d{1,9})?\\s*") String cap) {
        Integer capValue() {
            return cap == null || cap.isBlank() ? null : Integer.valueOf(cap.trim());
        }
    }

    /** The dates whose months periods are generated for, both inclusive; a missing one is the sheet's today. */
    public record GenerateRequest(LocalDate from, LocalDate to) {
    }

    /** A fiscal year, by the calendar year its first day falls in: four digits. */
    public record GenerateFiscalYearRequest(@NotNull @Pattern(regexp = "\\s*\\d{4}\\s*") String year) {
        int yearValue() {
            return Integer.parseInt(year.trim());
        }
    }

    /** A calendar year: four digits. */
    public record GenerateQuartersRequest(@NotNull @Pattern(regexp = "\\s*\\d{4}\\s*") String year) {
        int yearValue() {
            return Integer.parseInt(year.trim());
        }
    }

    /** The pasted lines of {@code name,period,amount}. */
    public record OpeningImportRequest(@NotNull @Size(max = 200_000) String text) {
    }

    /** How many lines went through. */
    public record OpeningImportView(int set) {
    }

    private final PeriodService service;

    private final OpeningImportService openings;

    private final SheetHistory history;

    public PeriodController(PeriodService service, OpeningImportService openings, SheetHistory history) {
        this.service = service;
        this.openings = openings;
        this.history = history;
    }

    @GetMapping
    public List<PeriodView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        List<Period> periods = asOf == null ? service.list(sheetId.trim())
                : history.read(sheetId.trim(), asOf).periods();
        return periods.stream().map(PeriodView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PeriodRequest request) {
        return PeriodView.of(service.add(sheetId.trim(), user.trim(), request.name(), request.from(), request.to(),
                request.capValue()));
    }

    /** Generate one period per month between the dates: the periods made, in order. */
    @PostMapping("/generate")
    public List<PeriodView> generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody GenerateRequest request) {
        return service.generate(sheetId.trim(), user.trim(), request.from(), request.to()).stream()
                .map(PeriodView::of).toList();
    }

    /** Generate the fiscal year's twelve monthly periods: the periods made, in order. */
    @PostMapping("/generate-fy")
    public List<PeriodView> generateFiscalYear(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid GenerateFiscalYearRequest request) {
        return service.generateFiscalYear(sheetId.trim(), user.trim(), request.yearValue()).stream()
                .map(PeriodView::of).toList();
    }

    /** Roll the fiscal year over: the next fiscal year's periods made, in order. */
    @PostMapping("/rollover")
    public List<PeriodView> rollover(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid GenerateFiscalYearRequest request) {
        return service.rollover(sheetId.trim(), user.trim(), request.yearValue()).stream()
                .map(PeriodView::of).toList();
    }

    /** Undo the sheet's last rollover: its generated periods removed and its opening balances taken back. */
    @PostMapping("/rollover/undo")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void undoRollover(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        service.undoRollover(sheetId.trim(), user.trim());
    }

    /** Generate the calendar year's four quarterly periods: the periods made, in order. */
    @PostMapping("/generate-quarters")
    public List<PeriodView> generateQuarters(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid GenerateQuartersRequest request) {
        return service.generateQuarters(sheetId.trim(), user.trim(), request.yearValue()).stream()
                .map(PeriodView::of).toList();
    }

    @PostMapping("/{periodId}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.close(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/soft-close")
    public PeriodView softClose(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.softClose(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/reopen")
    public PeriodView reopen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.reopen(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/lock")
    public PeriodView lock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.lock(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/unlock")
    public PeriodView unlock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.unlock(sheetId.trim(), user.trim(), periodId));
    }

    /** Paste opening balances: how many lines went through. */
    @PostMapping("/openings/import")
    public OpeningImportView importOpenings(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid OpeningImportRequest request) {
        return new OpeningImportView(openings.importOpenings(sheetId.trim(), user.trim(), request.text()));
    }
}
